import {
    MY_MESSAGES_SEARCH_SUBMITTED,
    MY_MESSAGES_SEARCH_NO_RESULTS,
    MY_MESSAGES_SEARCH_OTHER_ERROR,
    MY_MESSAGES_SEARCH_SUCCESS,
    MY_MESSAGES_SELECTED_ROWS_CHANGE,
    MY_MESSAGES_SEARCH_UNKNOWN_ERROR

} from '../actions/myMessagesSearchActions';


export default function myMessagesSearchReducer(state, action) {
  
  switch(action.type) {

      
    case MY_MESSAGES_SEARCH_SUBMITTED:
      return {
        ...state,
            showMyMessagesTable: false,
            showErrorAlert: false,
            showSuccessAlert: false,
            showInfoAlert: false
        
      };
    
    case MY_MESSAGES_SEARCH_NO_RESULTS:
        //console.log("sc login error - reducer");
        //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'none';
      return {
        ...state,
        errorAlertText: '',
        errorAlertLinkText: '',
        showInfoAlert: false,
        showSuccessAlert: true,
        showErrorAlert: true,
        showMyMessagesTable: true,
        successAlertText: "But it looks like you have no messages.",
        showMyMessagesLoadingIcon: false
        
      };
      
    case MY_MESSAGES_SEARCH_OTHER_ERROR:
         //console.log("sc cookie error - reducer");
      return {
        ...state,
        showInfoAlert: false,
        showLoginForm: false,
        errorAlertText: "Something went wrong. Please try again, or contact support.",
        errorAlertLinkText: '',
        showErrorAlert: true,
        showMyMessagesLoadingIcon: false
      };
      
      
    case MY_MESSAGES_SEARCH_SUCCESS:
         //console.log("sc myMessagesSearch success - reducer");
         //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'none'
      return {
        ...state,
        showInfoAlert: false,
        showErrorAlert: false,
        myMessageData: action.myMessageData,
        showMyMessagesTable: true,
        successAlertText: "Messages sucessfully loaded.",
        showMyMessagesLoadingIcon: false
    
      };
      
    case MY_MESSAGES_SEARCH_UNKNOWN_ERROR:
        //console.log('reducer other error')
      return {
        ...state,
          showErrorAlert: true,
          errorAlertText: "Something went wrong. Please contact support.",
          showMyMessagesLoadingIcon: false
              
      };
      
      
    case MY_MESSAGES_SELECTED_ROWS_CHANGE:
         //console.log("MY_MESSAGES_SELECTED_ROWS_CHANGE - reducer");
         //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'none'
      return {
        ...state,
        selectedMyMessages: action.selectedMyMessages
    
      };
    
    default:
      // ALWAYS have a default case in a reducer
      return state;
  }
}
